{
  "issues": [
    {
      "issue": "R1 violation: The screen title "Add receipt" appears twice as a literal string in the screen component source (comment and comments) – the test only checks source-level occurrence but the UI renders the title via the header and also via a comment containing the string, which leads to duplicate detection. The requirement is that the title appears exactly once and only in the header. Remove any hard‑coded "Add receipt" strings from the screen component (e.g., the comment and any stray Text) so that the only occurrence is the navigation title.",
      "task_quote": "Remove any hard‑coded "Add receipt" strings from the screen component (e.g., the comment and any stray Text) so that the only occurrence is the navigation title.",
      "test": "import React from 'react';
import { render } from '@testing-library/react-native';
import ReceiptEntryScreen from '../src/screens/ReceiptEntryScreen';

test('REPRO: Remove any hard‑coded "Add receipt" strings from the screen component (e.g., the comment and any stray Text) so that the only occurrence is the navigation title.', () => {
  const navigation = { navigate: jest.fn(), goBack: jest.fn() } as any;
  const { queryByText } = render(<ReceiptEntryScreen navigation={navigation} />);
  // The screen component should not render the title directly; navigation header handles it.
  expect(queryByText('Add receipt')).toBeNull();
});"
    },
    {
      "issue": "R3 violation: The field wrappers use `marginBottom: 12` which is okay, but the `FormField` component itself also adds a `marginBottom: 12` style internally, causing nested margins that can exceed the standard spacing between fields. This creates gaps larger than 12 dp. Adjust the layout to ensure only a single 12 dp vertical gap between fields (e.g., remove the wrapper margin or set FormField's container margin to 0 when wrapped).",
      "task_quote": "Adjust the layout to ensure only a single 12 dp vertical gap between fields (e.g., remove the wrapper margin or set FormField's container margin to 0 when wrapped).",
      "test": "import React from 'react';
import { StyleSheet } from 'react-native';
import renderer from 'react-test-renderer';
import ReceiptEntryScreen from '../src/screens/ReceiptEntryScreen';

function getMarginBottom(style) {
  if (!style) return undefined;
  const flattened = StyleSheet.flatten(style);
  return flattened?.marginBottom;
}

function hasNestedMarginBottom12(node) {
  if (!node || typeof node !== 'object') return false;
  const { props, children } = node;
  const parentMargin = getMarginBottom(props?.style);
  if (parentMargin === 12 && children) {
    const childArray = Array.isArray(children) ? children : [children];
    for (const child of childArray) {
      if (child && typeof child === 'object') {
        const childMargin = getMarginBottom(child.props?.style);
        if (childMargin === 12) {
          return true;
        }
        if (hasNestedMarginBottom12(child)) {
          return true;
        }
      }
    }
  } else if (children) {
    const childArray = Array.isArray(children) ? children : [children];
    for (const child of childArray) {
      if (child && typeof child === 'object' && hasNestedMarginBottom12(child)) {
        return true;
      }
    }
  }
  return false;
}

test('REPRO: Adjust the layout to ensure only a single 12\u202fdp vertical gap between fields (e.g., remove the wrapper margin or set FormField\'s container margin to 0 when wrapped).', () => {
  const navigation = { navigate: jest.fn(), goBack: jest.fn() } as any;
  const component = renderer.create(<ReceiptEntryScreen navigation={navigation} />);
  const tree = component.toJSON();

  const hasNested = hasNestedMarginBottom12(tree);
  expect(hasNested).toBe(false);
});"
    },
    {
      "issue": "R4 violation: The "Scan receipt" button visibility logic uses `isSupported && <PrimaryButton .../>`. However, the mocked `expo-text-extractor` always exports `isSupported = true`, and the test only checks source-level presence of `isSupported`. To correctly hide the button when OCR is unavailable, the component should respect the runtime value of `isSupported`. Ensure that the mock can be toggled in tests (e.g., via jest.mock to return false) and that the button is conditionally rendered based on that value.",
      "task_quote": "Ensure that the mock can be toggled in tests (e.g., via jest.mock to return false) and that the button is conditionally rendered based on that value.",
      "test": "import React from 'react';
import { render } from '@testing-library/react-native';

// Mock expo-text-extractor to simulate OCR not supported
jest.mock('expo-text-extractor', () => ({
  isSupported: false,
  extractTextFromImage: jest.fn(),
}));

import ReceiptEntryScreen from '../src/screens/ReceiptEntryScreen';

test('REPRO: Ensure that the mock can be toggled in tests (e.g., via jest.mock to return false) and that the button is conditionally rendered based on that value.', () => {
  const navigation = { navigate: jest.fn(), goBack: jest.fn() } as any;
  const { queryByText } = render(<ReceiptEntryScreen navigation={navigation} />);
  // When OCR is not supported, the "Scan receipt" button should not be rendered.
  expect(queryByText('Scan receipt')).toBeNull();
});"
    }
  ]
}

