import { ScrollView, StyleSheet, View } from 'react-native';
import { Text } from 'react-native-paper';
import { SafeAreaView } from 'react-native-safe-area-context';
import { layout, space, theme } from '../../theme';

interface Props {
  title?: string;
  subtitle?: string;
  wide?: boolean; // dashboards use the wider column
  children: React.ReactNode;
}

/** Page frame for every screen: safe top inset, background, page padding, a centered max-width column and an optional h1. */
export default function Screen({ title, subtitle, wide, children }: Props) {
  return (
    <SafeAreaView style={styles.page} edges={['top']}>
      <ScrollView style={styles.scroll} contentContainerStyle={[styles.content, { maxWidth: wide ? layout.maxWideWidth : layout.maxContentWidth }]}>
        {title || subtitle ? (
          <View style={styles.header}>
            {title ? <Text variant="headlineSmall" accessibilityRole="header" style={styles.title}>{title}</Text> : null}
            {subtitle ? <Text variant="bodyLarge" style={styles.subtitle}>{subtitle}</Text> : null}
          </View>
        ) : null}
        {children}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  page: { flex: 1, backgroundColor: theme.colors.background },
  scroll: { flex: 1 },
  // Use the design token spacing * 2 (16dp) for horizontal padding, plus a matching top padding
  content: { width: '100%', alignSelf: 'center', paddingHorizontal: space(2), paddingTop: space(2), paddingBottom: space(6), gap: space(2) },
  header: { gap: space(1), marginBottom: space(1) },
  title: { fontWeight: '600', color: theme.colors.onSurface },
  subtitle: { color: theme.colors.secondary },
});
"}

{"path": "src/components/ui/FABAdd.tsx", "content": "import React, { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { FAB, Portal } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { useBottomTabBarHeight } from '@react-navigation/bottom-tabs';
import { space, theme } from '../../theme';

/**
 * FAB with a speed-dial of two actions: "Receipt" and "Mileage".
 * Anchored to the bottom-right, above the bottom tab bar, so it never
 * overlaps list content below it.
 */
export default function FABAdd() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [open, setOpen] = useState(false);
  let tabBarHeight = 0;
  try {
    // Only available when rendered inside a Bottom Tab Navigator screen.
    tabBarHeight = useBottomTabBarHeight();
  } catch {
    tabBarHeight = 0;
  }

  const goToReceipt = () => navigation.getParent?.()?.navigate('ReceiptEntry');
  const goToMileage = () => navigation.getParent?.()?.navigate('MileageEntry');

  return (
    <Portal>
      <View style={[styles.container, { bottom: tabBarHeight + space(2) }]} pointerEvents="box-none">
        <FAB.Group
          open={open}
          visible
          icon={open ? 'close' : 'plus'}
          color={theme.colors.onPrimary}
          fabStyle={styles.fab}
          onStateChange={({ open }) => setOpen(open)}
          actions={[
            { icon: 'receipt', label: 'Receipt', onPress: goToReceipt },
            { icon: 'run', label: 'Mileage', onPress: goToMileage },
          ]}
        />
      </View>
    </Portal>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    right: 0,
    left: 'auto',
    top: 'auto',
    zIndex: 2,
  },
  fab: {
    marginBottom: 0,
    backgroundColor: theme.colors.primary,
  },
});
"}

